;; clojure.core overlay shard — reference :doc/:arglists/:tag for the image-baked
;; namespaces. GENERATED by tools/gen-core-docs.sh — do not edit by hand.
;;
;; Docstrings and arglists are from Clojure 1.12.5 (EPL-1.0,
;; (c) Rich Hickey and contributors — https://github.com/clojure/clojure).
;;
;; Loaded LAST in the prelude (after every tier and image stdlib ns), so a
;; :doc or :arglists the jolt source itself declares always wins — this file
;; only fills what the source did not carry: native primitives (map/reduce/+
;; are def-var!'d in Scheme with no meta) and ported sources whose docstrings
;; were dropped. Lookup goes through jolt.host/find-var, NOT clojure.core
;; find-var/resolve, so a tree-shaken build neither bails nor roots the
;; documented vars; a var absent at runtime is silently skipped.

;; :tag is the reference's own: a Class where the reference wrote the tag in a
;; metadata map ((defn not {:tag Boolean} ...) evaluates it), a symbol where it
;; wrote a ^Hint.

(defn- attach-core-doc-meta!
  [ns-name var-name doc args tag]
  (when-let [v (jolt.host/find-var ns-name var-name)]
    (alter-meta! v
      (fn [m]
        (let [m (if (and doc (nil? (get m :doc))) (assoc m :doc doc) m)
              m (if (and tag (nil? (get m :tag))) (assoc m :tag tag) m)]
          (if (and args (nil? (get m :arglists))) (assoc m :arglists args) m))))))

